import {api} from './api.js';
import {months,money,cents,dateText,periodDates,payroll,bankSummary,csv,uuid,escapeHtml as esc} from './logic.js';
import {readWorkbook,prepareImport} from './import.js';
const $=s=>document.querySelector(s),root=$('#app'),dialog=$('#dialog');
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M7 14h2 M15 14h2 M7 18h2',wallet:'M3 6h17v15H3z M3 6V3h14v3 M15 11h6v6h-6z',bank:'M3 9h18 M12 3l10 6H2z M5 10v8 M10 10v8 M15 10v8 M20 10v8 M2 21h20',report:'M4 3h11l5 5v13H4z M14 3v6h6 M8 13h8 M8 17h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',up:'M12 17V5 M7 10l5-5 5 5 M4 17v4h16v-4',check:'M5 12l4 4L19 6',chevron:'M9 5l7 7-7 7',refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 13-3l2 2 M4 17l2 2a8 8 0 0 0 13-3',edit:'M4 16L16 4l4 4L8 20H4z M14 6l4 4',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',close:'M6 6l12 12 M18 6L6 18',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.wallet}"/></svg>`;
const brand=`<div class="brand"><span class="symbol">p</span><div class="word">PRID<span>pay</span></div></div>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});
const initialYear=Number(today().slice(0,4));
const state={demo:false,user:null,view:'dashboard',year:initialYear,month:Number(today().slice(5,7)),ledgers:[],ledger:null,periods:[],entries:[],bankMonths:[],bankEntries:[],selected:null,tab:'all',filter:'',authMode:'login',loading:false};
let importDraft=null,toastTimer;
const owned=()=>state.demo||state.ledger?.owner_id===state.user?.id;
const sum=(rows,key)=>rows.reduce((n,r)=>n+Number(r[key]||0),0);
const calculations=()=>payroll(state.periods,state.entries,state.ledger?.opening_due_cents||0);
const yearRows=()=>calculations().filter(p=>p.year===state.year);
const activeRows=()=>yearRows().filter(p=>p.status!=='planned');
const selected=()=>calculations().find(p=>p.id===state.selected);
const badge=status=>`<span class="badge ${esc(status)}">${({open:'In progress',review:'Needs review',closed:'Reviewed',planned:'Planned',confirmed:'Confirmed',pending:'Pending'})[status]||esc(status)}</span>`;
const btn=(action,label,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function modal(title,body,onSubmit){$('#dialog-body').innerHTML=`<div class="modalhead"><h2>${title}</h2>${btn('close',icon('close'),'ghost iconbtn','aria-label="Close dialog"')}</div><div class="modalbody">${body}</div>`;if(!dialog.open)dialog.showModal();const form=dialog.querySelector('form');if(form&&onSubmit)form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.formerror').textContent='';try{await onSubmit(new FormData(form),form)}catch(error){form.querySelector('.formerror').textContent=error.message}finally{submit.disabled=false;}});}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const moneyfield=(label,name,value=0,extra='')=>field(label,name,Number(value)/100,'number',`step="0.01" ${extra}`);
const selectfield=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const footer=(save='Save changes')=>`<div class="formerror" role="alert"></div><div class="formactions">${btn('close','Cancel')}<button type="submit" class="primary">${save}</button></div>`;
async function reload(){
 if(state.demo)return;
 const ledgers=await api.list('pay_ledgers','order=created_at.asc');state.ledgers=ledgers;state.ledger=ledgers.find(l=>l.id===state.ledger?.id)||ledgers[0]||null;
 if(state.ledger){const id=state.ledger.id;[state.periods,state.entries,state.bankMonths,state.bankEntries]=await Promise.all([api.list('pay_periods',`ledger_id=eq.${id}&order=year.asc,month.asc`),api.list('pay_entries',`ledger_id=eq.${id}&order=updated_at.asc`),api.list('bank_months','order=year.asc,month.asc'),api.list('bank_entries','order=entry_date.desc')]);}else{state.periods=[];state.entries=[];state.bankMonths=[];state.bankEntries=[];}
}
async function save(table,data,id){if(state.demo){const key={pay_ledgers:'ledgers',pay_periods:'periods',pay_entries:'entries',bank_months:'bankMonths',bank_entries:'bankEntries'}[table];const item={id:id||uuid(),...data,updated_at:new Date().toISOString(),updated_by:state.user.id};if(id)state[key]=state[key].map(r=>r.id===id?{...r,...item}:r);else state[key].push(item);if(table==='pay_ledgers')state.ledger=state.ledgers.find(l=>l.id===(id||item.id));return[item];}const key={pay_periods:'periods',pay_entries:'entries'}[table],expected=key&&id?state[key].find(r=>r.id===id)?.updated_at:null;return id?api.update(table,id,data,expected):api.insert(table,data);}
async function remove(table,id){if(state.demo){const key={pay_periods:'periods',pay_entries:'entries',bank_entries:'bankEntries'}[table];state[key]=state[key].filter(r=>r.id!==id);if(table==='pay_periods')state.entries=state.entries.filter(r=>r.period_id!==id);}else await api.remove(table,id);}
async function finish(message){await reload();dialog.close();render();toast(message);}
function auth(){root.innerHTML=`<div class="auth"><section class="auth-story">${brand}<div class="auth-copy"><div class="eyebrow" style="color:#b4d29a">A LITTLE CLARITY GOES A LONG WAY</div><h1>Your hard work.<br>Your money.<br><em>All in balance.</em></h1><p>A simpler place for pay, everyday expenses, and the little details that add up.</p><div class="mini-ledger"><div class="smalltext" style="color:#b5c8aa">ONE CLEAR MONTHLY STATEMENT</div><div class="balance-row"><span>Pay + additions</span><strong>+</strong></div><div class="balance-row"><span>Agreed deductions</span><strong>−</strong></div><div class="balance-row"><span>Payments received</span><strong>−</strong></div><div class="balance-row"><span>Carried forward</span><strong>✓</strong></div></div></div><div class="auth-features"><span>↗ Year-by-year history</span><span>◎ Private bank tracking</span><span>✓ Shared pay records</span></div></section><section class="auth-main"><div class="auth-form"><div class="eyebrow">WELCOME TO PRID PAY</div><h2>${state.authMode==='signup'?'Start with a clear picture.':state.authMode==='recover'?'Reset your password.':'Good to see you.'}</h2><p class="subtitle">${state.authMode==='signup'?'Create your account to keep every month in order.':state.authMode==='recover'?'We’ll send a password reset link to your email.':'Sign in to pick up where you left off.'}</p><form id="auth-form">${field('Email address','email','','email','required autocomplete="email"')}${state.authMode==='recover'?'':field('Password','password','','password',`required minlength="10" autocomplete="${state.authMode==='signup'?'new-password':'current-password'}"`)}<div class="formerror" role="alert"></div><button class="primary" type="submit">${state.authMode==='signup'?'Create account':state.authMode==='recover'?'Send reset link':'Sign in'} &nbsp; →</button></form><p class="smalltext muted" style="margin-top:19px">${state.authMode==='login'?`New here? ${btn('auth-signup','Create an account','textlink')}`:`Already have an account? ${btn('auth-login','Sign in','textlink')}`}</p>${state.authMode==='login'?`<p style="margin-top:12px">${btn('auth-recover','Forgot your password?','textlink')}</p>`:''}<div class="splitline">TAKE A LOOK FIRST</div>${btn('demo','Explore a sample dashboard &nbsp; →','demo-button')}<p class="privacy">${icon('shield')} &nbsp;Your records are protected by sign-in. Pay sharing is optional; your bank transactions stay private.</p></div></section></div>`;
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;const data=new FormData(f),email=data.get('email').trim();try{if(state.authMode==='recover'){await api.recover(email);modal('Check your reset email',`<p class="subtitle">Copy the reset link from the email and paste it here, or enter the email code. This works even if the email link does not bring you back to the app.</p><form>${field('Reset link or code','verification','','text','required autocomplete="off"')}${footer('Verify reset request')}</form>`,async fd=>{await api.verify(email,fd.get('verification').trim(),'recovery');state.user=api.user;await reload();render();passwordModal();});return;}if(state.authMode==='signup'){await api.signup(email,data.get('password'));if(!api.user){modal('Check your email',`<p class="subtitle">Open the confirmation email for <strong>${esc(email)}</strong>, confirm your address, then return here to sign in. You can also copy the confirmation link from the email and paste it below, or enter its code.</p><form>${field('Confirmation link or code','code','','text','required autocomplete="one-time-code"')}${footer('Verify email')}</form>`,async fd=>{await api.verify(email,fd.get('code').trim());state.user=api.user;await reload();dialog.close();render();});return;}}else await api.login(email,data.get('password'));state.user=api.user;await reload();render();}catch(error){f.querySelector('.formerror').textContent=error.message}finally{b.disabled=false;}});
}
function demo(){state.demo=true;state.user={id:'demo-owner',email:'sample@example.com'};state.ledger={id:'demo-ledger',name:'PRID Pay',owner_id:'demo-owner',default_pay_cents:250000,opening_due_cents:0};state.ledgers=[state.ledger];state.periods=[];state.entries=[];state.bankMonths=[{id:'bm1',year:initialYear,month:1,opening_override_cents:85000}];state.bankEntries=[];let due=0;for(let m=1;m<=10;m++){const id='demo-'+m,base=250000,extras=m%3===0?17500:0,deduct=14000+(m%2===0?2000:0),payment=m<9?base+extras-deduct:m===9?150000:0;state.periods.push({id,ledger_id:'demo-ledger',year:initialYear,month:m,...periodDates(initialYear,m),base_pay_cents:base,status:m<9?'closed':'open',notes:''});const make=(kind,amount,desc)=>({id:uuid(),ledger_id:'demo-ledger',period_id:id,kind,amount_cents:amount,description:desc,entry_date:`${initialYear}-${String(m).padStart(2,'0')}-15`,method:kind==='payment'?'Zelle':'',status:'confirmed',notes:''});state.entries.push(make('deduction',14000,'Mobile plan'));if(m%2===0)state.entries.push(make('deduction',2000,'Transfer fee'));if(extras)state.entries.push(make('addition',extras,'Travel reimbursement'));if(payment){const p=make('payment',payment,'Monthly pay transfer');state.entries.push(p);state.bankEntries.push({id:uuid(),owner_id:'demo-owner',entry_date:p.entry_date,description:'Pay received',amount_cents:payment,category:'Pay',linked_payment_id:p.id});}state.bankEntries.push({id:uuid(),owner_id:'demo-owner',entry_date:`${initialYear}-${String(m).padStart(2,'0')}-20`,description:'Rent and living expenses',amount_cents:-125000,category:'Living'});}
 state.year=initialYear;state.view='dashboard';state.selected=null;render();}
function yearSelect(){const ys=[...new Set([initialYear,initialYear-1,initialYear+1,state.year,...state.periods.map(p=>p.year),...state.bankMonths.map(p=>p.year),...state.bankEntries.map(e=>Number(e.entry_date.slice(0,4)))])].sort((a,b)=>b-a);return `<select class="year-select" id="year" aria-label="Select year">${ys.map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select>`;}
function shell(content){const names={dashboard:'Overview',months:'Monthly pay',payments:'Payments',bank:'My bank',reports:'Reports',settings:'Settings',period:'Monthly statement'},nav=[['dashboard','dashboard','Overview'],['months','calendar','Monthly pay'],['payments','wallet','Payments'],...(owned()?[['bank','bank','My bank']]:[]),['reports','report','Reports']];root.innerHTML=`<div class="shell"><aside class="sidebar">${brand}<div class="workspace"><div class="avatar">P</div><div><b>${esc(state.ledger?.name||'Your workspace')}</b><span class="muted">Personal pay ledger</span></div></div><div class="navlabel">WORKSPACE</div><nav>${nav.map(([v,i,l])=>btn('nav',`${icon(i)}<span>${l}</span>`,state.view===v||v==='months'&&state.view==='period'?'active':'',`data-view="${v}" aria-label="${l}"`)).join('')}</nav><div class="bottom"><div class="help"><strong>A clearer month ahead.</strong><p class="muted" style="margin-top:5px">Add expenses as you go.<br>Let the balances follow.</p></div><nav>${btn('nav',`${icon('settings')}<span>Settings</span>`,state.view==='settings'?'active':'','data-view="settings" aria-label="Settings"')}</nav><div class="user"><div class="avatar">${esc((state.user?.email||'U').slice(0,2).toUpperCase())}</div><div><strong>${state.demo?'Sample workspace':owned()?'Your account':'Collaborator'}</strong>${btn('logout',state.demo?'Exit sample':'Sign out','signout')}</div></div></div></aside><main class="main"><header class="topbar"><div class="trail">Workspace <span>/</span><strong style="color:#49634f">${names[state.view]}</strong></div><div class="right">${state.demo?'<span class="demo-tag">SAMPLE DATA</span>':'<span class="smalltext muted"><i class="statusdot"></i>Cloud connected</span>'}<span class="today muted">${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'America/New_York'})}</span>${btn('refresh',icon('refresh'),'ghost iconbtn','aria-label="Refresh records"')}</div></header><div class="content">${state.demo?`<div class="data-message">You’re exploring sample data. Changes here last only until you leave this page. ${btn('logout','Sign in to save your own records →','ghost small')}</div>`:''}${!state.ledger?welcome():content}<div class="tagline">${icon('shield')} ${state.demo?'Sample workspace · No real financial records':'Private by default · Shared only when you choose'}</div></div></main></div>`;
 $('#year')?.addEventListener('change',e=>{state.year=Number(e.target.value);render();});$('#bank-month')?.addEventListener('change',e=>{state.month=Number(e.target.value);render();});$('#search')?.addEventListener('input',e=>{state.filter=e.target.value;filterRows();});}
function head(eyebrow,title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,foot,ico,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-number">${money(value)}</div><div class="stat-footer">${foot}</div></div>`;}
function welcome(){return `${head('A FRESH START','Let’s get your pay in order.','Create your private ledger, then add a month or bring in your Excel file.')}<div class="card"><div class="empty"><h2>A home for every pay period.</h2><p>Pay, additions, deductions and transfers.<br>Connected month to month, with no spreadsheet formulas to maintain.</p><p style="margin-top:25px">${btn('create-ledger',`${icon('plus')} &nbsp; Create my pay ledger`,'primary')}</p></div></div>`;}
function tablePeriods(rows){return `<div class="table-wrap"><table><thead><tr><th>Pay period</th><th class="amount">Net earned</th><th class="amount">Received</th><th class="amount">Carry forward</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(p=>`<tr><td><div class="period-name"><span class="month-icon">${String(p.month).padStart(2,'0')}</span><div>${months[p.month-1]} ${p.year}<span class="sub">${dateText(p.start_date)} – ${dateText(p.end_date)}</span></div></div></td><td class="amount">${money(p.earned)}</td><td class="amount">${money(p.payments)}</td><td class="amount ${p.closing<0?'negative':''}">${money(p.closing)}</td><td>${badge(p.status)}${p.pending?`<span class="sub">${p.pending} pending</span>`:''}</td><td>${btn('period',icon('chevron'),'ghost iconbtn',`data-id="${p.id}" aria-label="Open ${months[p.month-1]}"`)}</td></tr>`).join(''):'<tr><td colspan="6"><div class="empty">No pay periods in this year yet.<br>Add a month or import your Excel workbook.</div></td></tr>'}</tbody></table></div>`;}
function overview(){const rows=activeRows(),pending=rows.reduce((s,p)=>s+p.pending,0),closing=rows.at(-1)?.closing||0,net=sum(rows,'earned'),paid=sum(rows,'payments');return `${head('YOUR MONEY, AT A GLANCE','A little more peace of mind.',`Here’s how your ${state.year} is adding up.`,`${yearSelect()}${btn('export','Export','',`title="Download yearly CSV"`)}${btn('add-period',`${icon('plus')} &nbsp; Add month`,'primary')}`)}<div class="stats">${stat('Carried forward',closing,closing<0?'Advance to offset against future pay':'Unpaid balance through latest active period','wallet',true)}${stat('Net pay earned',net,'Base pay + additions − deductions','up')}${stat('Payments received',paid,'Confirmed receipts allocated to these periods','down')}${stat('Agreed deductions',sum(rows,'deductions'),`${rows.length} active pay period${rows.length===1?'':'s'} this year`,'report')}</div><div class="grid-main"><section class="card"><div class="cardhead"><div><h2>Your year in view</h2><p>Net earned and received, by pay period</p></div><span class="chip">${state.year}</span></div>${chart(rows)}<div class="legend"><span><i></i>Net earned</span><span class="paid"><i></i>Received</span></div></section><section class="card"><div class="cardhead"><div><h2>Where things stand</h2><p>A simple pay reconciliation</p></div>${icon('wallet')}</div><div class="balance-list"><div class="balance-row"><span class="muted">Opening carried balance</span><strong>${money(rows[0]?.opening||0)}</strong></div><div class="balance-row"><span class="muted">Net pay earned</span><strong>${money(net)}</strong></div><div class="balance-row"><span class="muted">Payments received</span><strong>− ${money(paid)}</strong></div>${rows.some(p=>p.carryDifference)?`<div class="balance-row"><span class="muted">Opening balance resets</span><strong>${money(sum(rows.slice(1),'carryDifference'))}</strong></div>`:''}<div class="balance-row balance-total"><span>Carried forward</span><strong>${money(closing)}</strong></div></div><div class="note">${pending?`${pending} pending item${pending===1?' needs':'s need'} your review. Pending items are excluded from these totals.`:'A positive balance is still owed to you. A negative balance is an advance against future pay.'}</div></section></div><section class="card"><div class="cardhead"><div><h2>Monthly pay</h2><p>Every period, neatly connected.</p></div>${btn('nav','View all months &nbsp; →','ghost small','data-view="months"')}</div>${tablePeriods(yearRows().slice(-5).reverse())}<div class="tablefoot"><span>USD · Pay periods usually run from the 19th to the 18th</span><span>${yearRows().length} periods</span></div></section>`;}
function chart(rows){const max=Math.max(100000,...rows.flatMap(p=>[p.earned,p.payments])),top=Math.ceil(max/100000)*100000;return `<div class="chart" role="img" aria-label="Monthly net earned and received bar chart. Exact amounts are available in the monthly pay table."><div class="axis">${[1,.75,.5,.25,0].map(x=>`<span>${x?`${(top*x/100000).toFixed(1)}k`:'0'}</span>`).join('')}</div><div class="chart-body">${Array.from({length:12},(_,i)=>{const r=rows.find(p=>p.month===i+1);return `<div class="bar-group" title="${months[i]}: net ${money(r?.earned||0)}, received ${money(r?.payments||0)}"><div class="bar" style="height:${Math.max(0,(r?.earned||0)/top*100)}%"></div><div class="bar paid" style="height:${Math.max(0,(r?.payments||0)/top*100)}%"></div><span class="bar-label">${months[i].slice(0,3)}</span></div>`}).join('')}</div></div>`;}
function monthsView(){return `${head('MONTH BY MONTH','Every month has a story.','Open a pay period to see its additions, deductions, and payments.',`${yearSelect()}${owned()?btn('import',`${icon('up')} &nbsp; Import Excel`):''}${btn('add-period',`${icon('plus')} &nbsp; Add month`,'primary')}`)}<section class="card">${tablePeriods(yearRows().reverse())}<div class="tablefoot"><span>Planned periods are excluded from yearly totals and carry-forward.</span><span>${yearRows().length} periods</span></div></section>`;}
function entriesTable(entries,opts={}){return `<div class="table-wrap"><table><thead><tr><th>Description</th><th>Date / method</th><th class="amount">Amount</th><th>Status</th><th class="no-print"></th></tr></thead><tbody>${entries.length?entries.map(e=>`<tr data-search="${esc((e.description+' '+e.notes+' '+e.method).toLowerCase())}"><td><strong>${esc(e.description)}</strong><span class="sub">${esc(e.kind[0].toUpperCase()+e.kind.slice(1))}${e.source_ref?' · '+esc(e.source_ref):''}</span>${e.notes?`<span class="sub">${esc(e.notes)}</span>`:''}</td><td>${dateText(e.entry_date)}<span class="sub">${esc(e.method||'—')}</span></td><td class="amount ${e.kind==='deduction'?'negative':''}">${money(e.amount_cents)}</td><td>${badge(e.status)}</td><td class="no-print">${btn('edit-entry',icon('edit'),'ghost iconbtn',`data-id="${e.id}" aria-label="Edit ${esc(e.description)}"`)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">No entries here yet. Add one when it happens.</div></td></tr>'}</tbody></table></div>`;}
function periodView(){const p=selected();if(!p){state.view='months';return monthsView();}const entries=p.rows.filter(e=>state.tab==='all'||e.kind===state.tab);return `${btn('nav','← &nbsp; All months','back','data-view="months"')}${head('MONTHLY STATEMENT',`${months[p.month-1]} ${p.year}`,`${dateText(p.start_date)} – ${dateText(p.end_date)} &nbsp; · &nbsp; ${badge(p.status)}`,`${btn('edit-period','Edit month')}${btn('print','Print statement')}${btn('add-entry',`${icon('plus')} &nbsp; Add entry`,'primary',`data-period="${p.id}"`)}`)}${p.pending?`<div class="warn">${p.pending} item${p.pending===1?' is':'s are'} waiting for confirmation. Add the actual payment date and confirm each receipt. Pending items do not change your balance.</div>`:''}${p.carryDifference?`<div class="warn">This month has a manual opening balance of ${money(p.opening)}. It differs from the preceding calculated balance by ${money(p.carryDifference)}. Review the opening balance in Edit month.</div>`:''}<div class="stats">${stat('Opening carry',p.opening,'From the previous active period','calendar')}${stat('Net earned',p.earned,'This period only','up')}${stat('Received',p.payments,'Confirmed payments','down')}${stat('Carry forward',p.closing,p.closing<0?'Advance against future pay':'Still owed after this period','wallet',true)}</div><div class="detail-grid"><section class="card"><div class="cardhead"><div><h2>Month’s activity</h2><p>Additions, deductions and payment receipts.</p></div>${btn('add-entry',icon('plus'),'ghost iconbtn',`data-period="${p.id}" aria-label="Add entry"`)}</div><div class="tabs no-print" style="margin:0 23px 4px">${[['all','All entries'],['deduction','Deductions'],['addition','Additions'],['payment','Payments'],['adjustment','Adjustments']].map(([v,l])=>btn('tab',l,state.tab===v?'active':'',`data-tab="${v}"`)).join('')}</div>${entriesTable(entries)}</section><section class="card"><div class="cardhead"><h2>Pay breakdown</h2>${icon('report')}</div><div class="balance-list">${[['Opening carry',p.opening],['Base pay',p.base_pay_cents],['Additions',p.additions],['Deductions',-p.deductions],['Adjustments',p.adjustments],['Received',-p.payments]].map(([l,v])=>`<div class="balance-row"><span class="muted">${l}</span><strong>${money(v)}</strong></div>`).join('')}<div class="balance-row balance-total"><span>Closing carry</span><strong>${money(p.closing)}</strong></div>${p.source_total_cents!=null?`<div class="balance-row"><span class="muted">Original Excel closing</span><strong>${money(p.source_total_cents)}</strong></div><p class="print-note">Excel comparison: ${money(p.closing-Number(p.source_total_cents))} difference. Pending receipts and opening balance resets can explain differences.</p>`:''}${p.notes?`<p class="print-note">${esc(p.notes)}</p>`:''}<p class="print-note">Last updated ${p.updated_at?new Date(p.updated_at).toLocaleString('en-US'):'in this session'}${p.updated_by?' · '+(p.updated_by===state.user.id?'by you':'by collaborator'):''}.</p></div><div class="note">Opening carry + base pay + additions − deductions + adjustments − confirmed payments.</div></section></div><p class="print-only print-note">${esc(state.ledger.name)} · Printed ${new Date().toLocaleDateString('en-US')} · Amounts in USD. Bank account details are excluded from this statement.</p>`;}
function paymentsView(){const ids=new Set(yearRows().map(p=>p.id)),entries=state.entries.filter(e=>e.kind==='payment'&&ids.has(e.period_id)).sort((a,b)=>(b.entry_date||'').localeCompare(a.entry_date||'')),paid=entries.filter(e=>e.status==='confirmed'),pending=entries.filter(e=>e.status==='pending');return `${head('A RECORD OF EVERY RECEIPT','Payments, without the guesswork.','Track when you were paid, how it arrived, and which pay period it belongs to.',`${yearSelect()}${btn('add-payment',`${icon('plus')} &nbsp; Record payment`,'primary')}`)}<div class="stats">${stat('Confirmed receipts',sum(paid,'amount_cents'),`Allocated to ${state.year} pay periods`,'wallet',true)}${stat('Pending receipts',sum(pending,'amount_cents'),`${pending.length} awaiting confirmation`,'calendar')}${stat('Via Zelle',sum(paid.filter(e=>e.method==='Zelle'),'amount_cents'),'Confirmed transfers','down')}${stat('In cash',sum(paid.filter(e=>e.method==='Cash'),'amount_cents'),'Confirmed cash payments','wallet')}</div><div class="filterbar"><input id="search" type="search" placeholder="Search payments…" aria-label="Search payments" value="${esc(state.filter)}"></div><div class="card">${entriesTable(entries)}<div class="tablefoot"><span>Dates may fall outside their allocated pay period. Cash is not automatically added to your bank.</span></div></div>`;}
function bankView(){if(!owned())return `<div class="empty">Your collaborator’s bank records are private.</div>`;const b=bankSummary(state.year,state.month,state.bankMonths,state.bankEntries),linked=state.bankEntries.filter(x=>x.linked_payment_id),mismatches=linked.filter(e=>{const p=state.entries.find(x=>x.id===e.linked_payment_id);return !p||p.status!=='confirmed'||Number(p.amount_cents)!==Number(e.amount_cents)||p.entry_date!==e.entry_date;});return `${head('YOUR PERSONAL BANK LEDGER','Know where your money goes.','Calendar-month bank activity, kept separate from your pay-period balance.',`${yearSelect()}<select class="year-select" id="bank-month" aria-label="Select bank month">${months.map((m,i)=>`<option value="${i+1}" ${state.month===i+1?'selected':''}>${m}</option>`).join('')}</select>${btn('add-bank',`${icon('plus')} &nbsp; Add transaction`,'primary')}`)}${mismatches.length?`<div class="warn">${mismatches.length} linked pay receipt${mismatches.length===1?' has':'s have'} changed. Review the linked bank transactions against your statement.</div>`:''}<div class="stats">${stat('Opening bank balance',b.opening,'Prior closing, or your entered opening','bank')}${stat('Money in',b.income,'Bank deposits dated this calendar month','down')}${stat('Money out',b.expenses,'Daily spending and withdrawals','up')}${stat('Calculated closing',b.closing,'Opening + money in − money out','wallet',true)}</div><div class="grid-main"><section class="card"><div class="cardhead"><div><h2>${months[state.month-1]} transactions</h2><p>Your bank account’s ins and outs.</p></div>${btn('link-payment','Add pay deposit','small')}</div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th class="amount">Amount</th><th></th></tr></thead><tbody>${b.rows.length?b.rows.sort((a,b)=>b.entry_date.localeCompare(a.entry_date)).map(e=>`<tr><td><strong>${esc(e.description)}</strong><span class="sub">${esc(e.category)}${e.linked_payment_id?' · Linked to pay':''}</span></td><td>${dateText(e.entry_date)}</td><td class="amount ${e.amount_cents<0?'negative':'positive'}">${money(e.amount_cents)}</td><td>${btn('edit-bank',icon('edit'),'ghost iconbtn',`data-id="${e.id}" aria-label="Edit transaction"`)}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty">Start with your opening bank balance,<br>then record deposits and daily expenses.</div></td></tr>'}</tbody></table></div></section><section class="card"><div class="cardhead"><div><h2>Match your bank statement</h2><p>Reconcile the month in one place.</p></div></div><div class="balance-list"><div class="balance-row"><span class="muted">Calculated closing</span><strong>${money(b.closing)}</strong></div><div class="balance-row"><span class="muted">Actual closing</span><strong>${b.actual==null?'Not entered':money(b.actual)}</strong></div><div class="balance-row balance-total"><span>Difference</span><strong class="${b.variance?'negative':''}">${b.variance==null?'—':money(b.variance)}</strong></div><div style="margin-top:20px">${btn('bank-balances','Set opening / closing balance','small')}</div></div><div class="note">Only record money that actually enters or leaves this bank account. A deduction from pay does not reduce your bank balance again.</div></section></div>`;}
function reports(){const rows=activeRows(),cashYear=state.entries.filter(e=>e.kind==='payment'&&e.status==='confirmed'&&e.entry_date?.startsWith(String(state.year))),category={};for(const e of state.entries.filter(e=>rows.some(p=>p.id===e.period_id)&&e.kind==='deduction'&&e.status==='confirmed'))category[e.description]=(category[e.description]||0)+Number(e.amount_cents);return `${head('THE BIGGER PICTURE','A year you can account for.','Review your earnings, deductions and receipts. Export whenever you need.',`${yearSelect()}${btn('export',`${icon('down')} &nbsp; Export CSV`,'primary')}`)}<div class="stats">${stat('Base pay',sum(rows,'base_pay_cents'),`${rows.length} active periods`,'report')}${stat('Additions',sum(rows,'additions'),'Allowances and reimbursements','up')}${stat('Net earned',sum(rows,'earned'),'Pay after confirmed deductions','wallet',true)}${stat('Received by payment date',sum(cashYear,'amount_cents'),`Receipts dated in calendar year ${state.year}`,'down')}</div><div class="grid-main"><section class="card"><div class="cardhead"><div><h2>Earned and received</h2><p>Allocated by pay period, not transfer date.</p></div></div>${chart(rows)}<div class="legend"><span><i></i>Net earned</span><span class="paid"><i></i>Received</span></div></section><section class="card"><div class="cardhead"><div><h2>Deduction breakdown</h2><p>Confirmed deductions in these pay periods.</p></div></div><div class="balance-list">${Object.entries(category).length?Object.entries(category).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([name,value])=>`<div class="balance-row"><span class="muted">${esc(name)}</span><strong>${money(value)}</strong></div>`).join(''):'<div class="empty">No deductions recorded yet.</div>'}</div></section></div><div class="card"><div class="cardhead"><h2>Yearly pay statement</h2></div>${tablePeriods(yearRows())}</div>`;}
function settings(){return `${head('MAKE IT YOURS','A few useful details.','Manage your ledger, shared access and your existing spreadsheet.')}<div class="settings-grid"><section class="card"><div class="cardhead"><h2>Pay ledger</h2>${icon('settings')}</div><div class="sectionbody"><p class="info-line"><span class="muted">Ledger name</span><br><strong>${esc(state.ledger.name)}</strong></p><p class="info-line"><span class="muted">Default monthly base pay</span><br><strong>${money(state.ledger.default_pay_cents)}</strong></p><p class="info-line"><span class="muted">Initial carried balance</span><br><strong>${money(state.ledger.opening_due_cents)}</strong></p>${owned()?btn('edit-ledger','Edit ledger details'):'<p class="note">Only the owner can change ledger settings.</p>'}</div></section><section class="card"><div class="cardhead"><h2>Work together</h2>${icon('shield')}</div><div class="sectionbody"><p class="info-line">Give your manager access to this pay ledger using their verified email address. Both accounts can update pay periods and entries.</p><p class="info-line"><span class="muted">Manager email</span><br><strong>${esc(state.ledger.manager_email||'Not shared yet')}</strong></p><p class="note">Bank balances and daily bank expenses stay private to your account. This does not send an invitation email; share the app link yourself.</p>${owned()?`<p style="margin-top:18px">${btn('share','Manage shared access')}</p>`:''}</div></section><section class="card"><div class="cardhead"><h2>Bring in your Excel</h2>${icon('up')}</div><div class="sectionbody"><p class="info-line">Import the monthly tabs from Pay @ Prid.xlsx. Choose the correct year and review the original closing balances before confirming.</p><p class="note">No year is assumed. Imported receipts need confirmation, and future periods are marked planned. Existing years cannot be overwritten by import.</p><p style="margin-top:18px">${owned()?btn('import','Import Excel workbook'):'Only the owner can import a workbook.'}</p></div></section><section class="card"><div class="cardhead"><h2>Your records, to go</h2>${icon('down')}</div><div class="sectionbody"><p class="info-line">Download pay activity for the selected year, or print any monthly statement to share with your manager.</p><p class="info-line"><span class="muted">Export year</span><br>${yearSelect()}</p>${btn('export','Download yearly CSV')}<p class="note" style="margin-top:20px">Bank tracking is a manual ledger. No online bank account is connected.</p></div></section></div>`;}
function render(){if(!state.user){auth();return;}const views={dashboard:overview,months:monthsView,period:periodView,payments:paymentsView,bank:bankView,reports,settings};shell(state.ledger?(views[state.view]||overview)():'');filterRows();}
function filterRows(){document.querySelectorAll('[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(state.filter.toLowerCase()));}
function editLedger(create=false){const l=state.ledger||{};modal(create?'Create your pay ledger':'Ledger details',`<p class="subtitle">Start with your regular pay. You can change it for individual months.</p><form><div class="formgrid"><label class="field full">Ledger name<input name="name" value="${esc(l.name||'PRID Pay')}" required maxlength="80"></label>${moneyfield('Default base pay ($)','pay',l.default_pay_cents??250000,'required min="0"')}${moneyfield('Initial carried balance ($)','opening',l.opening_due_cents||0)}<div class="field full"><p class="note">A positive carry means your employer owes you. A negative carry means an advance was already paid to you.</p></div></div>${footer(create?'Create ledger':'Save details')}</form>`,async f=>{await save('pay_ledgers',{name:f.get('name').trim(),default_pay_cents:cents(f.get('pay')),opening_due_cents:cents(f.get('opening')),owner_id:state.user.id},create?null:l.id);await finish(create?'Your ledger is ready.':'Ledger updated.');});}
function editPeriod(existing=null){const p=existing||{},dates=periodDates(state.year,state.month);modal(existing?'Edit pay period':'Add a pay period',`<form><div class="formgrid">${field('Year','year',p.year||state.year,'number','required min="2000" max="2100"')}${selectfield('Month (period ending)','month',months.map((m,i)=>[i+1,m]),p.month||state.month)}${field('Period starts','start',p.start_date||dates.start_date,'date','required')}${field('Period ends','end',p.end_date||dates.end_date,'date','required')}${moneyfield('Base pay ($)','base',p.base_pay_cents??state.ledger.default_pay_cents,'required min="0"')}${selectfield('Month status','status',[['open','In progress'],['review','Needs review'],['closed','Reviewed / closed'],['planned','Planned']],p.status||'open')}<label class="field full">Opening carry override ($) — leave blank to carry automatically<input name="opening" type="number" step="0.01" value="${p.opening_override_cents==null?'':p.opening_override_cents/100}"></label><label class="field full">Notes<textarea name="notes">${esc(p.notes||'')}</textarea></label></div><p class="note">Planned months are excluded from yearly totals. An opening override resets the balance for that period.</p>${footer(existing?'Save month':'Add month')}${existing?`<p style="margin-top:18px">${btn('delete-period','Delete this month and its entries','danger small',`data-id="${p.id}"`)}</p>`:''}</form>`,async(f)=>{const year=Number(f.get('year')),month=Number(f.get('month'));if(state.periods.some(x=>x.year===year&&x.month===month&&x.id!==p.id))throw new Error('This month already exists. Open it to edit.');if(f.get('start')>f.get('end'))throw new Error('The start date must come before the end date.');if(f.get('status')==='closed'&&p.rows?.some(e=>e.status==='pending'))throw new Error('Review pending entries before closing this month.');await save('pay_periods',{ledger_id:state.ledger.id,year,month,start_date:f.get('start'),end_date:f.get('end'),base_pay_cents:cents(f.get('base')),opening_override_cents:f.get('opening')===''?null:cents(f.get('opening')),status:f.get('status'),notes:f.get('notes').trim()},p.id);state.year=year;await finish('Pay period saved.');});
 if(!existing){for(const name of ['year','month'])dialog.querySelector(`[name=${name}]`).addEventListener('change',()=>{const d=periodDates(Number(dialog.querySelector('[name=year]').value),Number(dialog.querySelector('[name=month]').value));dialog.querySelector('[name=start]').value=d.start_date;dialog.querySelector('[name=end]').value=d.end_date;});}}
function editEntry(id=null,period=null,kind='deduction'){if(!state.periods.length){toast('Add a pay period first.');editPeriod();return;}const e=state.entries.find(r=>r.id===id)||{};const p=period||e.period_id||state.selected||yearRows().at(-1)?.id||state.periods.at(-1).id;modal(id?'Edit pay entry':'Add pay entry',`<p class="subtitle">Pay deductions change what is owed. Record personal bank spending in My bank.</p><form><div class="formgrid">${selectfield('Pay period','period',state.periods.map(x=>[x.id,`${months[x.month-1]} ${x.year}`]),p)}${selectfield('Entry type','kind',[['deduction','Deduction from pay'],['addition','Addition to pay'],['payment','Payment received'],['adjustment','Signed balance adjustment']],e.kind||kind)}<label class="field full">Description<input name="description" value="${esc(e.description||'')}" required maxlength="200" placeholder="e.g. Mobile plan, travel reimbursement"></label>${moneyfield('Amount ($)','amount',e.amount_cents||0,'required')}${field('Date','date',id?e.entry_date||'':today(),'date')}${selectfield('Method','method',[['','Not applicable'],['Zelle','Zelle'],['Cash','Cash'],['Bank transfer','Bank transfer'],['Check','Check'],['Other','Other']],e.method||'')}${selectfield('Confirmation','status',[['confirmed','Confirmed'],['pending','Pending / needs review']],e.status||'confirmed')}<label class="field full">Notes<textarea name="notes">${esc(e.notes||'')}</textarea></label></div><p class="note">Payments require the actual date when confirmed. A signed adjustment adds to the amount owed when positive, and reduces it when negative. Cash receipts are separate from bank deposits.</p>${footer(id?'Save entry':'Add entry')}${id?`<p style="margin-top:18px">${btn('delete-entry','Delete entry','danger small',`data-id="${id}"`)}</p>`:''}</form>`,async f=>{const amount=cents(f.get('amount')),kind=f.get('kind'),status=f.get('status');if(amount===0)throw new Error('Enter an amount greater than zero, or a signed nonzero adjustment.');if(kind!=='adjustment'&&amount<0)throw new Error('Use a positive amount, or choose a signed balance adjustment.');if(kind==='payment'&&status==='confirmed'&&!f.get('date'))throw new Error('Add the actual payment date before confirming it.');await save('pay_entries',{ledger_id:state.ledger.id,period_id:f.get('period'),kind,description:f.get('description').trim(),amount_cents:amount,entry_date:f.get('date')||null,method:f.get('method'),status,notes:f.get('notes').trim()},id);await finish('Pay entry saved.');});}
function editBank(id=null){const e=state.bankEntries.find(r=>r.id===id)||{};modal(id?'Edit bank transaction':'Add bank transaction',`<p class="subtitle">Record money that actually entered or left your bank account.</p><form><div class="formgrid"><label class="field full">Description<input name="description" value="${esc(e.description||'')}" required maxlength="200" placeholder="e.g. Groceries, bank deposit"></label>${field('Date','date',e.entry_date||today(),'date','required')}${selectfield('Direction','direction',[['out','Money out / expense'],['in','Money in / deposit']],Number(e.amount_cents)>0?'in':'out')}${moneyfield('Amount ($)','amount',Math.abs(e.amount_cents||0),'required min="0.01"')}${selectfield('Category','category',['Food','Living','Transport','Shopping','Transfers','Pay','Other'].map(v=>[v,v]),e.category||'Other')}<label class="field full">Notes<textarea name="notes">${esc(e.notes||'')}</textarea></label></div>${e.linked_payment_id?'<p class="note">This transaction is linked to a pay receipt. Confirm any edits against your bank statement.</p>':''}${footer(id?'Save transaction':'Add transaction')}${id?`<p style="margin-top:18px">${btn('delete-bank','Delete bank transaction','danger small',`data-id="${id}"`)}</p>`:''}</form>`,async f=>{const amount=cents(f.get('amount'));if(amount<=0)throw new Error('Enter a positive amount.');await save('bank_entries',{owner_id:state.user.id,entry_date:f.get('date'),description:f.get('description').trim(),amount_cents:f.get('direction')==='out'?-amount:amount,category:f.get('category'),notes:f.get('notes').trim()},id);state.year=Number(f.get('date').slice(0,4));state.month=Number(f.get('date').slice(5,7));await finish('Bank transaction saved.');});}
function bankBalances(){const b=bankSummary(state.year,state.month,state.bankMonths,state.bankEntries),s=b.setting;modal(`${months[state.month-1]} bank balances`,`<form><div class="formgrid"><label class="field full">Opening bank balance ($) — blank carries prior closing<input name="opening" type="number" step="0.01" value="${s?.opening_override_cents==null?'':s.opening_override_cents/100}"></label><label class="field full">Actual closing from bank statement ($) — optional<input name="actual" type="number" step="0.01" value="${s?.actual_close_cents==null?'':s.actual_close_cents/100}"></label></div><p class="note">Calculated opening is ${money(b.opening)}. Enter the real balance at the start of your first tracked month. Actual closing is used for comparison; calculated carry-forward continues from your recorded transactions.</p>${footer('Save balances')}</form>`,async f=>{await save('bank_months',{owner_id:state.user.id,year:state.year,month:state.month,opening_override_cents:f.get('opening')===''?null:cents(f.get('opening')),actual_close_cents:f.get('actual')===''?null:cents(f.get('actual'))},s?.id);await finish('Bank balances updated.');});}
function linkPayment(){const entries=state.entries.filter(e=>e.kind==='payment'&&e.status==='confirmed'&&e.entry_date&&!state.bankEntries.some(b=>b.linked_payment_id===e.id));if(!entries.length){toast('No unlinked confirmed payments. Record a payment first.');return;}modal('Record a pay deposit',`<p class="subtitle">Choose a payment that actually reached your bank. Cash should only be added after you deposit it.</p><form>${selectfield('Pay receipt','payment',entries.map(e=>[e.id,`${dateText(e.entry_date)} · ${money(e.amount_cents)} · ${e.method||'Other'}`]),entries[0].id)}<p class="note">Use Add transaction for a cash deposit made on a different day. Linking the same receipt twice is blocked.</p>${footer('Add to bank ledger')}</form>`,async f=>{const e=entries.find(x=>x.id===f.get('payment'));await save('bank_entries',{owner_id:state.user.id,entry_date:e.entry_date,description:e.description,amount_cents:e.amount_cents,category:'Pay',notes:`Pay receipt via ${e.method||'other method'}`,linked_payment_id:e.id});await finish('Pay deposit added to your bank ledger.');});}
function share(){modal('Shared pay access',`<form>${field('Manager’s verified email','email',state.ledger.manager_email||'','email','placeholder="manager@example.com"')}<p class="note">This account can read and edit your pay periods and pay entries. They cannot access your bank ledger or change sharing settings. Leave the email blank to remove access.</p><label class="check" style="margin-top:18px"><input type="checkbox" name="confirm" required>I want to grant or update access for this email.</label>${footer('Update access')}</form>`,async f=>{await save('pay_ledgers',{manager_email:f.get('email').trim().toLowerCase()||null},state.ledger.id);await finish('Shared access updated. Share the app link with your manager.');});}
function confirmDelete(table,id){modal('Delete this record?',`<p class="subtitle">${table==='pay_periods'?'This deletes the month and every pay entry in it.':'This permanently removes this entry.'} Linked bank records remain separate, and may need review.</p><form>${footer('Delete record')}</form>`,async()=>{await remove(table,id);if(table==='pay_periods'){state.selected=null;state.view='months';}await finish('Record deleted.');});}
function showImport(){importDraft=null;modal('Bring your Excel into focus',`<p class="subtitle">Select your original pay workbook. It is read in your browser. Nothing is saved until you confirm the preview.</p><form>${field('Year these monthly tabs belong to','year','','number','required min="2000" max="2100" placeholder="Enter the workbook year"')}<label class="field" style="margin-top:18px">Excel workbook (.xlsx)<input name="file" type="file" accept=".xlsx" required></label><p class="note">Use an empty year. Amounts and original closing totals are preserved. Receipts stay pending until you confirm dates and receipt details.</p>${footer('Preview import')}</form>`,async f=>{const year=Number(f.get('year'));if(state.periods.some(p=>p.year===year))throw new Error('This year already has pay periods. Import into an empty year to avoid duplicates.');const file=f.get('file');const sheets=readWorkbook(await file.arrayBuffer());importDraft={...prepareImport(sheets,year),year};previewImport();});}
function previewImport(){const d=importDraft;modal('Review your imported year',`<p class="subtitle">${d.periods.length} months · ${d.entries.length} entries · ${d.year}. Check the year carefully before saving.</p><div class="import-table"><table><thead><tr><th>Period</th><th class="amount">Base pay</th><th class="amount">Excel closing</th><th>Review</th></tr></thead><tbody>${d.periods.map(p=>`<tr><td>${months[p.month-1]}</td><td class="amount">${money(p.base_pay_cents)}</td><td class="amount">${money(p.source_total_cents)}</td><td>${d.entries.filter(e=>e.period_id===p.id&&e.status==='pending').length} receipts</td></tr>`).join('')}</tbody></table></div><div class="warn">Imported payments stay pending, including items such as “Need for home.” Negative receipts become signed adjustments for review. Dates and notes need confirmation; no bank transactions are created.</div><form><label class="check"><input name="confirm" type="checkbox" required>I confirm these tabs belong to ${d.year}, and I will review pending receipts.</label>${footer('Import these records')}</form>`,async()=>{if(state.demo){for(const p of d.periods)state.periods.push({...p,year:d.year,ledger_id:state.ledger.id});for(const e of d.entries)state.entries.push({...e,ledger_id:state.ledger.id});}else await api.rpc('import_pay_year',{p_ledger:state.ledger.id,p_year:d.year,p_periods:d.periods,p_entries:d.entries});state.year=d.year;state.view='months';await finish('Imported. Open each month to review its pending receipts.');importDraft=null;});}
function exportCsv(){const periods=yearRows(),ids=new Set(periods.map(p=>p.id)),rows=[['PRID PAY YEARLY STATEMENT',state.year],['Amounts in USD. Planned periods excluded from annual totals.'],[],['Month','Status','Opening carry','Base pay','Additions','Deductions','Adjustments','Confirmed payments','Closing carry','Pending items','Original Excel closing']];for(const p of periods)rows.push([`${months[p.month-1]} ${p.year}`,p.status,p.opening/100,p.base_pay_cents/100,p.additions/100,p.deductions/100,p.adjustments/100,p.payments/100,p.closing/100,p.pending,p.source_total_cents==null?'':p.source_total_cents/100]);rows.push([],['PAY ENTRIES'],['Month','Kind','Description','Amount','Actual date','Method','Status','Notes','Source cell']);for(const e of state.entries.filter(e=>ids.has(e.period_id))){const p=periods.find(p=>p.id===e.period_id);rows.push([`${p.year}-${String(p.month).padStart(2,'0')}`,e.kind,e.description,e.amount_cents/100,e.entry_date,e.method,e.status,e.notes,e.source_ref]);}const blob=new Blob(['\ufeff'+csv(rows)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`PRID-Pay-${state.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Yearly statement downloaded.');}
async function action(name,el){switch(name){case'close':dialog.close();return;case'auth-signup':state.authMode='signup';auth();return;case'auth-login':state.authMode='login';auth();return;case'auth-recover':state.authMode='recover';auth();return;case'demo':demo();return;case'logout':if(!state.demo)await api.logout();state.demo=false;state.user=null;state.ledger=null;state.view='dashboard';state.filter='';auth();return;case'nav':state.view=el.dataset.view;state.filter='';state.tab='all';render();return;case'refresh':await reload();render();toast(state.demo?'Sample dashboard refreshed.':'Records refreshed.');return;case'create-ledger':editLedger(true);return;case'edit-ledger':editLedger();return;case'add-period':editPeriod();return;case'period':state.selected=el.dataset.id;state.view='period';state.tab='all';render();return;case'edit-period':editPeriod(selected());return;case'add-entry':editEntry(null,el.dataset.period);return;case'add-payment':editEntry(null,null,'payment');return;case'edit-entry':editEntry(el.dataset.id);return;case'tab':state.tab=el.dataset.tab;render();return;case'add-bank':editBank();return;case'edit-bank':editBank(el.dataset.id);return;case'bank-balances':bankBalances();return;case'link-payment':linkPayment();return;case'share':share();return;case'import':showImport();return;case'export':exportCsv();return;case'print':window.print();return;case'delete-entry':confirmDelete('pay_entries',el.dataset.id);return;case'delete-bank':confirmDelete('bank_entries',el.dataset.id);return;case'delete-period':confirmDelete('pay_periods',el.dataset.id);return;}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;try{await action(el.dataset.action,el)}catch(error){toast(error.message);}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function passwordModal(){modal('Choose a new password',`<form>${field('New password','password','','password','required minlength="10" autocomplete="new-password"')}${footer('Save password')}</form>`,async f=>{await api.changePassword(f.get('password'));dialog.close();toast('Password updated.');});}
async function init(){try{const type=await api.acceptHash();state.user=api.user;if(state.user){await reload();render();if(type==='recovery')passwordModal();}else auth();}catch(error){auth();toast(error.message);}}
window.addEventListener('storage',e=>{if(e.key==='prid-session'&&!e.newValue&&!state.demo){state.user=null;auth();}});
init();
